  procedure: z.array(procedureStepSchema).min(1),
  output: z.object({schemaId: z.string().regex(/^[a-z][a-z0-9_.-]*$/), fields: z.array(procedureOutputFieldSchema).min(1)}).strict(),
  evidence: z.object({
